/* v62: mã QR nộp tiền */
.bn-qr { margin-top:14px; border:2px solid var(--xanh); border-radius:16px; padding:12px; background:#fff; display:grid; gap:10px; }
.bn-qr-dau { display:flex; align-items:center; gap:8px; font-weight:800; color:var(--xanh-dam); font-size:16px; flex-wrap:wrap; } .bn-qr-dau span { font-weight:600; color:var(--xam); font-size:13.5px; }
.bn-qr-than { display:grid; grid-template-columns:auto minmax(0,1fr); gap:12px; align-items:center; }
.bn-qr-anh { width:200px; height:200px; image-rendering:pixelated; border:1px solid var(--vien); border-radius:10px; background:#fff; }
.bn-qr-tt { display:grid; grid-template-columns:auto minmax(0,1fr); gap:3px 10px; font-size:14px; } .bn-qr-tt span { color:var(--xam); } .bn-qr-tt b { word-break:break-word; }
.bn-qr-canh, .bn-qr-loi { display:flex; gap:8px; align-items:flex-start; background:#fffbeb; border:1.5px solid #f59e0b; color:#78350f; border-radius:12px; padding:10px 12px; font-size:14px; line-height:1.5; } .bn-qr-canh .ic, .bn-qr-loi .ic { flex:none; margin-top:2px; }
.bn-qr-loi { background:#fff1f0; border-color:#f5b5ae; color:#8a1c14; }
.bn-qr-nut { display:grid; grid-template-columns:1fr 1fr; gap:8px; } .bn-qr-nut .nut { justify-content:center; }
@media (max-width:520px) { .bn-qr-than { grid-template-columns:1fr; justify-items:center; } .bn-qr-anh { width:min(260px, 78vw); height:auto; } .bn-qr-tt { width:100%; } }
.tkn-ds { display:grid; gap:8px; margin:10px 0; }
.tkn-dong { display:flex; gap:10px; align-items:center; border:1px solid var(--vien); border-left:4px solid #9aa5b4; border-radius:12px; padding:10px 12px; }
.tkn-dong.tt-ok { border-left-color:var(--la); } .tkn-dong.tt-cho { border-left-color:#f59e0b; } .tkn-dong.tt-sai { border-left-color:var(--do); } .tkn-dong.tt-tat { opacity:.6; }
.tkn-tt { flex:1; min-width:0; display:grid; gap:2px; font-size:14px; } .tkn-tt small { color:var(--xam); font-size:12.5px; }
.tkn-nhan { justify-self:start; font-size:12px; font-weight:800; padding:2px 9px; border-radius:999px; } .tkn-nhan.xanh { background:var(--la2); color:var(--la); } .tkn-nhan.do { background:var(--do2); color:var(--do); } .tkn-nhan.vang { background:#fff3c4; color:#7a5c00; } .tkn-nhan.xam { background:#eef2f7; color:var(--xam); }
.tkn-luoi { display:grid; grid-template-columns:repeat(auto-fit, minmax(200px,1fr)); gap:10px; margin:6px 0 10px; } .tkn-luoi label { display:grid; gap:4px; }
.tkn-khac { display:flex; gap:8px; align-items:flex-start; background:#fff1f0; border:1px solid #f5b5ae; border-radius:10px; padding:8px 10px; margin-bottom:10px; font-size:14px; } .tkn-khac.an { display:none; } .tkn-khac input { width:20px; height:20px; flex:none; }
.tkn-cho { border:2px solid #f59e0b; background:#fffbeb; border-radius:14px; padding:12px 14px; margin:10px 0; display:grid; gap:8px; color:#5a3e00; } .tkn-cho.an { display:none; }
.tkn-cho-dau { display:flex; align-items:center; gap:8px; font-size:15.5px; color:#7a4b00; }
.tkn-cho-tk { display:grid; grid-template-columns:auto 1fr; gap:3px 12px; background:#fff; border-radius:10px; padding:8px 12px; font-size:15px; } .tkn-cho-tk span { color:var(--xam); }
      <div class="tkn-cho an" id="nbTKCho" role="alert"></div>
      <div class="the" id="tknThe">
        <h3><i class=ic data-ic=bank></i> Tài khoản nhận tiền của cán bộ (mã QR nộp tiền)</h3>
        <p class="nho">Khách bấm <b>Nộp tiền</b> sẽ thấy mã QR chuyển khoản – đúng số tiền tháng đó, nội dung có mã khách hàng – vào tài khoản của <b>cán bộ quản lý địa bàn</b> tháng hóa đơn. An toàn 4 lớp: phải nhập lại mật khẩu · <b>chính cán bộ</b> đăng nhập xác nhận · Claude <b>khóa vân tay</b> vào mã nguồn (lệnh "update QR") · lệch là tự ẩn QR + báo Telegram.</p>
        <div id="tknDs" class="tkn-ds"><div class="nho">Đang tải…</div></div>
        <form id="fTKN" class="chi-adm tkn-form" autocomplete="off">
          <div class="tkn-luoi">
            <label><span class="nhan-o">Cán bộ</span><select id="tknCB" class="day"></select></label>
            <label><span class="nhan-o">Ngân hàng</span><select id="tknNH" class="day"></select></label>
            <label><span class="nhan-o">Số tài khoản</span><input id="tknStk" class="day" inputmode="numeric" maxlength="23" placeholder="Chỉ gồm chữ số"></label>
            <label><span class="nhan-o">Tên chủ tài khoản</span><input id="tknChu" class="day" maxlength="50" placeholder="Như trên thẻ / app ngân hàng"></label>
          </div>
          <label class="tkn-khac an" id="tknKhacL"><input type="checkbox" id="tknKhac"> <span>Tên chủ tài khoản <b>khác</b> tên cán bộ – tôi đã kiểm tra, vẫn lưu</span></label>
          <button class="nut" type="submit" id="nutTKN"><i class=ic data-ic=lock></i> Lưu tài khoản (nhập lại mật khẩu)</button>
          <div class="loi" id="loiTKN"></div>
        </form>
      </div>
